<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useRoute} from 'vue-router'
import {api} from '../../shared/api/ApiClient'
import {auth} from '../auth/AuthService'
import {teamService,type Member} from '../team/TeamService'
const team=String(useRoute().params.team),base=`/teams/${team}/knowledge`
interface Box{id:string;name:string;department:string;createdBy:string}
interface Document{id:string;boxId:string;title:string;content:string}
interface Agent{id:string;name:string;department:string}
interface Answer{answer:string;provider:string;citations:{sourceId:string;title:string;quote:string}[];tools:{name:string;status:string;sources:number}[]}
const data=ref<{boxes:Box[];documents:Document[];agents:Agent[]}>({boxes:[],documents:[],agents:[]}),members=ref<Member[]>([]),isOwner=ref(false)
const boxName=ref(''),department=ref(''),selected=ref(''),title=ref(''),content=ref(''),saveApproved=ref(false),agentName=ref(''),assigned=ref<string[]>([]),agentId=ref(''),question=ref(''),queryApproved=ref(false),answer=ref<Answer|null>(null),recipient=ref(''),grants=ref<string[]>([]),busy=ref(false),error=ref('')
async function load(){data.value=await api.request(base);members.value=await teamService.members(team);isOwner.value=(await teamService.list()).some(t=>t.id===team&&t.role==='OWNER')}
async function run(action:()=>Promise<unknown>){busy.value=true;error.value='';try{await action();await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function showGrants(){grants.value=[];if(selected.value&&data.value.boxes.some(b=>b.id===selected.value&&b.createdBy===auth.user?.id))grants.value=await api.request<string[]>(`${base}/boxes/${selected.value}/grants`)}
async function ask(){answer.value=null;await run(async()=>{answer.value=await api.request<Answer>(`${base}/agents/${agentId.value}/ask`,'POST',{question:question.value,approved:true})})}
const owns=computed(()=>data.value.boxes.some(b=>b.id===selected.value&&b.createdBy===auth.user?.id))
const others=computed(()=>members.value.filter(m=>m.id!==auth.user?.id))
function createBox(){return run(async()=>{await api.request(base+'/boxes','POST',{name:boxName.value,department:department.value});boxName.value=''})}
function createDocument(){return run(async()=>{await api.request(base+'/documents','POST',{boxId:selected.value,title:title.value,content:content.value,approved:saveApproved.value});title.value='';content.value='';saveApproved.value=false})}
function createAgent(){return run(async()=>{await api.request(base+'/agents','POST',{name:agentName.value,department:department.value,boxIds:assigned.value});agentName.value='';assigned.value=[]})}
function grant(allowed:boolean){return run(async()=>{await api.request(`${base}/boxes/${selected.value}/grants`,'PUT',{userId:recipient.value,allowed});await showGrants()})}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section><RouterLink class="back" :to="`/teams/${team}`">팀 회의로 돌아가기</RouterLink><h1>팀 자료함</h1><p>부서 자료를 보관하고, 지정한 자료를 읽는 에이전트에게 질문하세요. 내 접근 권한과 에이전트 배정 범위가 모두 허용하는 자료만 사용합니다.</p><p v-if="error" role="alert" class="notice error">{{error}}</p><div class="two-columns"><div><h2>접근 가능한 자료함</h2><p v-if="!data.boxes.length" class="empty">아직 공유된 자료가 없습니다. 아래에서 자료함을 만들거나 소유자에게 접근 권한을 요청하세요.</p><label>자료함<select v-model="selected" @change="showGrants().catch(e=>error=e.message)"><option value="">자료함 선택</option><option v-for="box in data.boxes" :key="box.id" :value="box.id">{{box.department}} · {{box.name}}</option></select></label><ul class="task-list"><li v-for="doc in data.documents.filter(d=>d.boxId===selected)" :key="doc.id"><details><summary>{{doc.title}}</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{doc.content}}</pre></details></li></ul><details><summary>자료함 만들기</summary><form @submit.prevent="createBox"><label>자료함 이름<input v-model="boxName" required maxlength="80"></label><label>부서 이름<input v-model="department" required maxlength="80"></label><button :disabled="busy">자료함 생성</button></form></details><template v-if="owns"><details><summary>자료 등록</summary><form @submit.prevent="createDocument"><label>제목<input v-model="title" required maxlength="160"></label><label>자료 원문<textarea v-model="content" required maxlength="20000" rows="8"/></label><label class="check"><input v-model="saveApproved" type="checkbox">서버 저장 및 권한을 부여한 팀원에게 공유하는 데 동의합니다.</label><button :disabled="busy||!saveApproved">자료 저장</button></form></details><details><summary>팀원 읽기 권한</summary><label>팀원<select v-model="recipient"><option value="">선택</option><option v-for="member in others" :key="member.id" :value="member.id">{{member.name}} · {{grants.includes(member.id)?'허용':'미허용'}}</option></select></label><div class="actions"><button :disabled="busy||!recipient" @click="grant(true)">읽기 허용</button><button class="secondary" :disabled="busy||!recipient" @click="grant(false)">권한 해제</button></div></details></template></div><div><h2>자료 기반 질의</h2><form @submit.prevent="ask"><label>에이전트<select v-model="agentId" required><option value="">에이전트 선택</option><option v-for="agent in data.agents" :key="agent.id" :value="agent.id">{{agent.department}} · {{agent.name}}</option></select></label><label>질문<textarea v-model="question" required maxlength="2000" rows="3"/></label><label class="check"><input v-model="queryApproved" type="checkbox">AI가 질문과 허용된 자료를 분석합니다. 관리자 설정에 따라 외부 API로 전환될 수 있습니다.</label><button :disabled="busy||!queryApproved">{{busy?'자료를 확인하고 있습니다…':'에이전트에게 질문'}}</button></form><div v-if="answer" aria-live="polite"><p class="record-note">{{answer.provider==='external'?'외부 API 사용':'로컬 모델 사용'}} · 검토용 답변</p><p style="white-space:pre-wrap">{{answer.answer}}</p><details><summary>도구 호출 이력</summary><ul><li v-for="(tool,i) in answer.tools" :key="i">{{tool.name}} · {{tool.status}} · 근거 {{tool.sources}}개</li></ul></details><details v-for="source in answer.citations" :key="source.sourceId"><summary>{{source.title}}</summary><blockquote>{{source.quote}}</blockquote></details></div><details v-if="isOwner"><summary>에이전트 만들기 · 팀 소유자</summary><form @submit.prevent="createAgent"><label>에이전트 이름<input v-model="agentName" required maxlength="80"></label><label>부서 이름<input v-model="department" required maxlength="80"></label><fieldset><legend>읽을 자료함</legend><label v-for="box in data.boxes" :key="box.id" class="check"><input v-model="assigned" type="checkbox" :value="box.id">{{box.name}}</label></fieldset><button :disabled="busy||!assigned.length">에이전트 생성</button></form></details></div></div></section></template>
